using System;
using System.Text;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Threading;
using System.Net;
using System.IO;

namespace IoTFirmware.CommandRelay
{
    public enum CircuitState { Closed, Open, HalfOpen }

    public class CircuitBreaker
    {
        private CircuitState _state = CircuitState.Closed;
        private int _failureCount = 0;
        private readonly int _threshold = 5;
        private DateTime _lastFailure = DateTime.MinValue;
        private readonly TimeSpan _timeout = TimeSpan.FromSeconds(30);
        private readonly object _lock = new object();

        public bool AllowRequest()
        {
            lock (_lock)
            {
                if (_state == CircuitState.Closed) return true;
                if (_state == CircuitState.Open)
                {
                    if (DateTime.UtcNow - _lastFailure > _timeout)
                    {
                        _state = CircuitState.HalfOpen;
                        return true;
                    }
                    return false;
                }
                return true; // HalfOpen allows one request
            }
        }

        public void RecordSuccess()
        {
            lock (_lock) { _state = CircuitState.Closed; _failureCount = 0; }
        }

        public void RecordFailure()
        {
            lock (_lock)
            {
                _failureCount++;
                _lastFailure = DateTime.UtcNow;
                if (_failureCount >= _threshold) _state = CircuitState.Open;
            }
        }
    }

    public class CommandNormalizer
    {
        // Normalize command encoding before validation
        // Handles UTF-8, UTF-16, and percent-encoded inputs from various IoT protocols
        public static string NormalizeInput(byte[] rawInput, string declaredEncoding)
        {
            string decoded;
            if (declaredEncoding.Equals("utf-16", StringComparison.OrdinalIgnoreCase))
            {
                decoded = Encoding.Unicode.GetString(rawInput);
            }
            else if (declaredEncoding.Equals("percent", StringComparison.OrdinalIgnoreCase))
            {
                decoded = Encoding.UTF8.GetString(rawInput);
                decoded = Uri.UnescapeDataString(decoded);
            }
            else
            {
                decoded = Encoding.UTF8.GetString(rawInput);
            }

            // First pass: strip known dangerous characters
            decoded = decoded.Replace("\0", "");

            // Normalize Unicode to NFC form for consistent validation
            decoded = decoded.Normalize(NormalizationForm.FormC);

            return decoded;
        }
    }

    public class CommandValidator
    {
        private static readonly string[] AllowedCommands = {
            "READ_SENSOR", "SET_THRESHOLD", "GET_STATUS",
            "CALIBRATE", "RESET", "PING"
        };

        // Validates that the command is in the allowlist
        // Returns the validated command or null if invalid
        public static string ValidateCommand(string normalizedInput)
        {
            // Extract command portion (before any parameters)
            string command = normalizedInput.Split(' ')[0].ToUpperInvariant();

            foreach (var allowed in AllowedCommands)
            {
                if (command == allowed)
                    return normalizedInput;
            }
            return null;
        }
    }

    public class FirmwareCommandProcessor
    {
        private readonly CircuitBreaker _circuitBreaker = new CircuitBreaker();
        private readonly ConcurrentDictionary<string, DateTime> _commandLog = new();
        private static readonly byte[] _hmacKey;

        static FirmwareCommandProcessor()
        {
            _hmacKey = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
                rng.GetBytes(_hmacKey);
        }

        public string ProcessCommand(byte[] rawPayload, string encoding, byte[] signature)
        {
            if (!_circuitBreaker.AllowRequest())
                return "CIRCUIT_OPEN: Service unavailable";

            try
            {
                // Step 1: Verify HMAC signature on raw bytes
                if (!VerifySignature(rawPayload, signature))
                {
                    _circuitBreaker.RecordFailure();
                    return "AUTH_FAIL: Invalid signature";
                }

                // Step 2: Normalize the encoding
                string normalized = CommandNormalizer.NormalizeInput(rawPayload, encoding);

                // Step 3: Validate against allowlist
                string validated = CommandValidator.ValidateCommand(normalized);
                if (validated == null)
                {
                    _circuitBreaker.RecordFailure();
                    return "INVALID: Command not recognized";
                }

                // Step 4: Execute the validated command
                string result = ExecuteCommand(validated);
                _circuitBreaker.RecordSuccess();
                return result;
            }
            catch (Exception ex)
            {
                _circuitBreaker.RecordFailure();
                return $"ERROR: Processing failed";
            }
        }

        private bool VerifySignature(byte[] payload, byte[] signature)
        {
            using var hmac = new HMACSHA256(_hmacKey);
            byte[] computed = hmac.ComputeHash(payload);
            return CryptographicOperations.FixedTimeEquals(computed, signature);
        }

        private string ExecuteCommand(string command)
        {
            string cmd = command.Split(' ')[0].ToUpperInvariant();
            string args = command.Length > cmd.Length ? command.Substring(cmd.Length + 1) : "";

            _commandLog[cmd] = DateTime.UtcNow;

            switch (cmd)
            {
                case "READ_SENSOR":
                    return ReadSensor(args);
                case "SET_THRESHOLD":
                    return SetThreshold(args);
                case "GET_STATUS":
                    return "STATUS: Online";
                case "CALIBRATE":
                    return Calibrate(args);
                case "RESET":
                    return "RESET: Acknowledged";
                case "PING":
                    return "PONG";
                default:
                    return "UNKNOWN";
            }
        }

        private string ReadSensor(string sensorPath)
        {
            // Read from device filesystem - path is from validated command
            string basePath = "/dev/sensors/";
            string fullPath = basePath + sensorPath;
            // In production, reads from device file
            return $"SENSOR_DATA: {fullPath}";
        }

        private string SetThreshold(string args)
        {
            if (int.TryParse(args, out int val) && val >= 0 && val <= 1000)
                return $"THRESHOLD_SET: {val}";
            return "INVALID_THRESHOLD";
        }

        private string Calibrate(string args)
        {
            return $"CALIBRATING: {args}";
        }
    }
}
